#外界渗透计划
touhou_rabbit_permeate = {
	touhou_RAB_all_right = {#万事俱备
		icon = generic_form_nation
		fire_only_once = yes
		allowed = {
			original_tag = RAB
		}

		available = {
			is_subject = no
			any_country = {
				original_tag = JAP
				NOT = { is_subject_of = RAB }
				NOT = { is_in_faction_with = RAB }
			}
		}

		visible = {
			original_tag = RAB
			has_completed_focus = touhou_RAB_exchange_all
		}

		complete_effect = {
			every_country = {
				limit = { 
					original_tag = JAP
					NOT = { is_subject_of = RAB }
					NOT = { is_in_faction_with = RAB }
				}
				every_core_state = {
					add_core_of = ROOT
				}
				every_country = {
					limit = {
						is_subject_of = PREV #prev可用于every系列
					}
					country_event = { id = touhou_ai.4 }
				}
				ROOT = {
					declare_war_on = {
						type = annex_everything
						target = PREV
					}
				}
			}
		}
		ai_will_do = {
			factor = 1
		}
	}
}
