#人偶的特殊用途
touhou_decisions_categories_doll = {
	touhou_mission_doll_production_line = {#人偶生产线
		activation = {
			has_manpower < 110000000
		}
		icon = generic_factory
		days_mission_timeout = 35
		is_good = yes
		available = {
			hidden_trigger = {
				always = no
			}
		}
		cancel_trigger = {
			has_manpower > 110000000
		}
		modifier = {
			consumer_goods_expected_value = 0.1
		}
		timeout_effect = {
			custom_effect_tooltip = touhou_mission_doll_production_line_manpower_tt
			hidden_effect = {
				#每段通过独立事件执行，避免同一效果块中的人力修改互相覆盖。
				add_manpower = var:touhou_var_alice_trait_manpower
				country_event = {
					id = alice.8
					hours = 1
				}
			}
		}
		ai_will_do = {
			factor = 200
		}
	}		
	touhou_mission_doll_automatic_construction = {#自动化人偶建设
		activation = {
			any_controlled_state = {
				free_building_slots = {
					building = infrastructure
					size > 0
				}				
			}
		}
		icon = generic_construction
		days_mission_timeout = 20
		is_good = yes
		fire_only_once = yes
		available = {
			hidden_trigger = {
				always = no
			}
		}
		cancel_trigger = {
			all_controlled_state = {
				free_building_slots = {
					building = infrastructure
					size < 1
				}	
			}
		}
		timeout_effect = {			
			random_controlled_state = {
				limit = { 
					free_building_slots = {
						building = infrastructure
						size > 0
					}
				}
				add_building_construction = {
					type = infrastructure
					level = 1
					instant_build = yes
				}
			}
			activate_mission = touhou_mission_doll_automatic_construction
		}
		ai_will_do = {
			factor = 200
		}
	}		
	touhou_decisions_sent_manpower_faction = {#输送人偶士兵
		icon = eng_propaganda_campaigns
		available = {
			has_manpower > 110000
		}	
		visible = {
			FROM = { 
				OR = {
					is_in_faction_with = ROOT
					is_subject_of = ROOT
				}
			}
		}
		target_trigger = {
			FROM = { 
				OR = {
					is_in_faction_with = ROOT
					is_subject_of = ROOT
				}
			}
		}
		days_remove = 30		
		fire_only_once = no
		ai_will_do = {
			base = 10
			modifier = {
				add = 1100
				FROM = { is_ai = no }
			}
		}
		cost = 50
		complete_effect = {			
			add_manpower = -110000			
			FROM = { add_manpower = 110000 }
		}
	}	
	touhou_decisions_strengthen_alice_doll_army = {#强化人偶作战网络-陆战
		icon = generic_army_support
		available = {
			has_manpower > 400000
		}
		cost = 50
		fire_only_once = yes
		ai_will_do = { factor = 1 }
		days_re_enable = 30
		complete_effect = {
			add_manpower = -400000
			add_to_variable = { 
				touhou_var_alice_doll_army_attack_factor = 0.05 								
			}
			add_to_variable = {
				touhou_var_alice_doll_army_defence_factor = 0.05
			}
			add_to_variable = {
				touhou_var_alice_doll_army_org_factor = 0.05
			}
			add_to_variable = {
				touhou_var_alice_doll_army_strength_factor = 0.02	
			}
		}
	}
	touhou_decisions_strengthen_alice_doll_naval = {#强化人偶作战网络-海战
		icon = generic_naval
		available = {
			has_manpower > 200000
		}
		cost = 50
		fire_only_once = yes
		ai_will_do = { factor = 1 }
		days_re_enable = 30
		complete_effect = {
			add_manpower = -200000
			add_to_variable = { 
				touhou_var_alice_doll_naval_damage_factor = 0.05 
			}
			add_to_variable = {
				touhou_var_alice_doll_naval_defense_factor = 0.05				
			}
			add_to_variable = {
				touhou_var_alice_doll_navy_org_factor = 0.05
			}
		}
	}
	touhou_decisions_strengthen_alice_doll_air = {#强化人偶作战网络-空战
		icon = generic_air
		available = {
			has_manpower > 200000
		}
		cost = 50
